import{_ as a,C as i,o as l,c as n,ak as c,E as o,j as t,a as r}from"./chunks/framework.DxrHb2fb.js";const f=JSON.parse('{"title":"RadioGroup 单选组","description":"","frontmatter":{},"headers":[],"relativePath":"components/radio-group.md","filePath":"components/radio-group.md","lastUpdated":1790174783000}'),h={name:"components/radio-group.md"};function s(u,d,b,p,g,m){const e=i("XhDemo");return l(),n("div",null,[d[0]||(d[0]=c('<h1 id="radiogroup-单选组" tabindex="-1">RadioGroup 单选组 <a class="header-anchor" href="#radiogroup-单选组" aria-label="Permalink to &quot;RadioGroup 单选组&quot;">​</a></h1><p>一组互斥选项共用一个值，所有选项同时可见。单个单选按钮是这里的 <code>item</code> 部件，不另立组件：它脱离组既没有互斥对象，也无法取消选中。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/radio-group" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/radio-group.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/radio-group" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/radio-group" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/radio-group.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>组内只有一个 Tab 停靠点，进组后四个方向键都能切换</p>',5)),o(e,{src:"radio-group/01-basic"}),d[1]||(d[1]=c('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;radio-group&quot;</code>：<code>root</code> · <code>label</code> · <strong><code>item</code></strong> · <code>item-text</code> · <code>indicator</code> · <code>hidden-input</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="受控" tabindex="-1">受控 <a class="header-anchor" href="#受控" aria-label="Permalink to &quot;受控&quot;">​</a></h3><p>传入 value 后由宿主决定；值可以是 null，表示没有任何一项选中</p>',6)),o(e,{src:"radio-group/02-controlled"}),d[2]||(d[2]=t("h3",{id:"横向排布",tabindex:"-1"},[r("横向排布 "),t("a",{class:"header-anchor",href:"#横向排布","aria-label":'Permalink to "横向排布"'},"​")],-1)),d[3]||(d[3]=t("p",null,"orientation 只影响排版与 aria-orientation，方向键四个方向照样都能切换",-1)),o(e,{src:"radio-group/03-horizontal"}),d[4]||(d[4]=t("h3",{id:"禁用",tabindex:"-1"},[r("禁用 "),t("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),d[5]||(d[5]=t("p",null,"单项禁用后不可点击，方向键也跳过它；整组禁用则每一项都随之禁用",-1)),o(e,{src:"radio-group/04-disabled"}),d[6]||(d[6]=t("h3",{id:"颜色",tabindex:"-1"},[r("颜色 "),t("a",{class:"header-anchor",href:"#颜色","aria-label":'Permalink to "颜色"'},"​")],-1)),d[7]||(d[7]=t("p",null,"tone 决定选中圆点使用哪族颜色，六种语气各一组",-1)),o(e,{src:"radio-group/05-tone"}),d[8]||(d[8]=t("h3",{id:"尺寸",tabindex:"-1"},[r("尺寸 "),t("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[9]||(d[9]=t("p",null,"size 改变条目间距与字号，不写即默认中档",-1)),o(e,{src:"radio-group/06-size"}),d[10]||(d[10]=t("h3",{id:"数据驱动",tabindex:"-1"},[r("数据驱动 "),t("a",{class:"header-anchor",href:"#数据驱动","aria-label":'Permalink to "数据驱动"'},"​")],-1)),d[11]||(d[11]=t("p",null,"数据字段的命名由数据决定，映射为条目的值、文本与禁用即可",-1)),o(e,{src:"radio-group/07-options"}),d[12]||(d[12]=c('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>二到五个互斥选项，且各选项的文字值得同时展开供用户比较。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>选项超过五六个时，使用<a href="./select">选择器</a>。</li><li>选项是并列的视图切换时，使用<a href="./toggle-group">切换按钮组</a>或<a href="./tabs">标签页</a>。</li><li>可以多选时，使用<a href="./checkbox-group">复选框组</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>整组只占一个 Tab 位，组内靠方向键移动，与原生单选组一致。</li><li><code>hidden-input</code> 承担表单参与。</li><li><code>collection</code> 可数据驱动，也可以逐项编写。</li><li>圆圈是字段家族的控制盒：不填底、描边与无影，选中后以语气色圆点填充；整行接 Action Control row 档，悬停 / 按下换面不缩放，圆圈随行换到承载面阶梯的下一档。</li><li>与<a href="./checkbox">复选框</a>的不对称是有意的：一个复选框自身即成立（勾选同意条款），一个单选按钮自身不成立，因此复选框有独立组件、单选按钮没有。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>外层放<a href="./field">表单字段</a>；每项的补充说明放进选项内容。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>提供默认选中项，除非“未选”本身有意义。</li><li>选项文字写完整，不依赖共同前缀省略。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>单选组只有一个选项，用户无从选择。</li><li>选项可以被取消选中：单选组一旦选中就不应回到空值，需要空值时增加一项“不指定”。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-radio-group&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhRadioGroupItem</code> <code>XhRadioGroupItemText</code> <code>XhRadioGroupLabel</code> <code>XhRadioGroupRoot</code></td></tr><tr><td>组合式函数</td><td><code>useRadioGroup</code></td></tr><tr><td>状态机</td><td><code>radioGroupMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/radio-group.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>RadioGroupNode[]</code></td><td></td><td>条目数据，显示文本与禁用的事实源。提供后条目部件只需声明 value。 未提供时回到文本与禁用都写在条目部件上的方式。</td></tr><tr><td><code>value</code></td><td><code>string | null</code></td><td></td><td></td></tr><tr><td><code>defaultValue</code></td><td><code>string | null</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：不可选择，但仍可聚焦、方向键照常移动焦点，对比度不降低。</td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败：只改变呈现，不阻止交互。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td>必填：随表单校验一起使用，只发无障碍属性，不自行拦截提交。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td></td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 &#39;ltr&#39;。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定使用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: RadioGroupValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化回调。</td></tr></tbody></table><h3 id="radiogroupnode" tabindex="-1">RadioGroupNode <a class="header-anchor" href="#radiogroupnode" aria-label="Permalink to &quot;RadioGroupNode&quot;">​</a></h3><p><code>collection</code> 的元素。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td><td>是</td><td></td></tr><tr><td><code>label</code></td><td><code>string</code></td><td></td><td>展示文本；默认回退为 value。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>条目禁用：方向键跳过它，但它仍可聚焦、仍是导航起点。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>RadioGroupValueChangeDetails</code></td><td>选中值变化；detail 为 <code>{ value: string | null }</code></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhRadioGroupItem</code></td><td><code>value</code></td><td><code>string</code></td><td>是</td><td></td></tr><tr><td><code>XhRadioGroupItem</code></td><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>默认交给 connect 查询 collection，写死 false 会覆盖数据中的禁用。</td></tr><tr><td><code>XhRadioGroupRoot</code></td><td><code>label</code></td><td><code>ReactNode</code></td><td></td><td>标题文字。提供后不必再写 label 部件。</td></tr><tr><td><code>XhRadioGroupRoot</code></td><td><code>renderItem</code></td><td><code>(node: RadioGroupNodeMeta) =&gt; ReactNode</code></td><td></td><td>每个条目的自定义内容；未提供时使用 collection 中的 label。</td></tr><tr><td><code>XhRadioGroupRoot</code></td><td><code>children</code></td><td><code>ReactNode</code></td><td></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>item</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item-text</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>indicator</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>hidden-input</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>ITEM.SELECT</code> · <code>ITEM.FOCUS</code> · <code>GROUP.BLUR</code> · <code>FORM.RESET</code> · <code>PRESS.START</code> · <code>PRESS.END</code></p><p><strong>判据</strong>：<code>canPress</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string | null</code></td><td></td></tr><tr><td><code>collection</code></td><td><code>readonly RadioGroupNodeMeta[]</code></td><td>由 collection 推导的条目元信息，按数据顺序排列；未提供 collection 时为空数组。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点在组外时为 null。</td></tr><tr><td><code>setValue</code></td><td><code>(next: string) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: RadioGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: RadioGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getIndicatorProps</code></td><td><code>(props: RadioGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>(props: RadioGroupItemProps) =&gt; T[&#39;input&#39;]</code></td><td>条目对应的隐藏原生 radio 输入，用于表单提交。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/radio/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the group</td><td>整组只占一个 Tab 位：焦点进入锚点条目（即选中项）；落到容器上时由容器转投锚点条目，锚点缺席或被禁用才落首个可停留项</td></tr><tr><td><code>ArrowDown</code> / <code>ArrowRight</code></td><td>focus in group, group not disabled</td><td>焦点移到下一个可停留条目并选中，末项回绕到首项；dir=rtl 时改由 ArrowLeft 承担</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowLeft</code></td><td>focus in group, group not disabled</td><td>焦点移到上一个可停留条目并选中，首项回绕到末项；dir=rtl 时改由 ArrowRight 承担</td></tr><tr><td><code>Space</code></td><td>focus on item, item not disabled</td><td>选中当前条目</td></tr><tr><td><code>Space</code></td><td>held on item, 条目未禁用且组未禁用、非只读</td><td>按住期间该条目投影 data-pressed，与指针 :active 同一副按压面（行与圆圈一起换面）；抬起或失焦撤下，按住途中整组转入禁用或只读也撤下。role=radio 只有 Space 是激活键，Enter 不进按压面；选中与按压互相独立</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>root</code></td><td><code>aria-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-required</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;radiogroup&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-checked</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;radio&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/radio-group.css</code> 使用 <code>[data-scope=&quot;radio-group&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-required</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>item</code></td><td><code>data-xh-action-display</code></td><td>&#39;always&#39;</td></tr><tr><td><code>item</code></td><td><code>data-xh-action-profile</code></td><td>&#39;row&#39;</td></tr><tr><td><code>item</code></td><td><code>data-xh-action-size</code></td><td>&#39;xs&#39;</td></tr><tr><td><code>item</code></td><td><code>data-xh-action-variant</code></td><td>&#39;ghost&#39;</td></tr><tr><td><code>item-text</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-text</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-text</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-text</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>indicator</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>hidden-input</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>hidden-input</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>hidden-input</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-radio-group-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>radio-group 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-bg</code></td><td><code>indicator</code></td><td><code>background</code></td><td><code>default</code></td><td><code>transparent</code></td><td>radio-group 的 indicator 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-bg-disabled</code></td><td><code>indicator</code><br><code>item</code></td><td><code>background</code></td><td><code>disabled</code></td><td><code>--xh-bg-subtle</code></td><td>radio-group 的 indicator、item 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-bg-pressed</code></td><td><code>indicator</code><br><code>item</code></td><td><code>background</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>not([data-disabled])</code><br><code>not([data-readonly])</code><br><code>pressed</code><br><code>readonly</code></td><td><code>--xh-_radio-group-host-bg-pressed</code></td><td>radio-group 的 indicator、item 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-border</code></td><td><code>indicator</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-border-control</code></td><td>radio-group 的 indicator 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-border-checked</code></td><td><code>indicator</code></td><td><code>border-color</code></td><td><code>state=checked</code></td><td><code>--xh-_radio-group-accent</code></td><td>radio-group 的 indicator 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-border-disabled</code></td><td><code>indicator</code><br><code>item</code></td><td><code>border-color</code></td><td><code>disabled</code></td><td><code>--xh-border-default</code></td><td>radio-group 的 indicator、item 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-border-hover</code></td><td><code>indicator</code><br><code>item</code></td><td><code>border-color</code></td><td><code>disabled</code><br><code>hover</code><br><code>invalid</code><br><code>not([data-disabled])</code><br><code>not([data-invalid])</code><br><code>not([data-readonly])</code><br><code>not([data-state=&#39;checked&#39;])</code><br><code>readonly</code><br><code>state=checked</code></td><td><code>--xh-border-control-hover</code></td><td>radio-group 的 indicator、item 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-border-invalid</code></td><td><code>indicator</code></td><td><code>border-color</code></td><td><code>invalid</code><br><code>state=checked</code></td><td><code>--xh-border-invalid</code></td><td>radio-group 的 indicator 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-dot</code></td><td><code>indicator</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-_radio-group-accent</code></td><td>radio-group 的 indicator 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-dot-disabled</code></td><td><code>indicator</code><br><code>item</code></td><td><code>background</code></td><td><code>disabled</code></td><td><code>--xh-fg-disabled</code></td><td>radio-group 的 indicator、item 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-dot-pressed</code></td><td><code>indicator</code><br><code>item</code></td><td><code>background</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>not([data-disabled])</code><br><code>not([data-readonly])</code><br><code>pressed</code><br><code>readonly</code><br><code>state=checked</code></td><td><code>--xh-_tone-active</code></td><td>radio-group 的 indicator、item 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-radius</code></td><td><code>indicator</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-circle</code></td><td>radio-group 的 indicator 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-indicator-size</code></td><td><code>indicator</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-_radio-group-indicator</code></td><td>radio-group 的 indicator 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-item-bg-hover</code></td><td><code>item</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>hover</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code></td><td><code>--xh-bg-subtle</code></td><td>radio-group 的 item 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-item-bg-pressed</code></td><td><code>item</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-bg-subtle-hover</code></td><td>radio-group 的 item 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-item-fg</code></td><td><code>item</code></td><td><code>color</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-fg-default</code></td><td>radio-group 的 item 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-item-fg-disabled</code></td><td><code>item</code></td><td><code>color</code></td><td><code>disabled</code></td><td><code>--xh-fg-disabled</code></td><td>radio-group 的 item 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-item-font-size</code></td><td><code>item</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_radio-group-font-size</code></td><td>radio-group 的 item 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-item-gap</code></td><td><code>item</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_radio-group-item-gap</code></td><td>radio-group 的 item 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-item-radius</code></td><td><code>item</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>radio-group 的 item 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-label-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>radio-group 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-label-fg-disabled</code></td><td><code>label</code><br><code>root</code></td><td><code>color</code></td><td><code>disabled</code></td><td><code>--xh-fg-subtle</code></td><td>radio-group 的 label、root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-label-font-size</code></td><td><code>label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-label-size</code></td><td>radio-group 的 label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-radio-group-label-font-weight</code></td><td><code>label</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>radio-group 的 label 部件 font-weight 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>background-color</code> · <code>border-color</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h3><p>皮肤另按输入能力分档：<code>pointer: coarse</code>：同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',61))])}const k=a(h,[["render",s]]);export{f as __pageData,k as default};
